function defaults(){return{betaAccepted:false,cardStats:{},customSets:[],sessions:[],profile:{notifications:true,autoRepeat:true,dailyGoal:20},theme:'system'}}
function loadState(){let r={};try{r=JSON.parse(localStorage.getItem('aq_state')||'{}')}catch{};const d=defaults();const s={...d,...r,profile:{...d.profile,...(r.profile||{})},cardStats:r.cardStats||{},customSets:Array.isArray(r.customSets)?r.customSets:[],sessions:Array.isArray(r.sessions)?r.sessions:[]};return s}
function save(){localStorage.setItem('aq_state',JSON.stringify(state))} function allSets(){return [...GRANULAR_SETS,...DEFAULT_SETS,...state.customSets]} function getSet(id){return allSets().find(x=>x.id===id)}
function esc(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))} function now(){return Date.now()} function days(n){return n*86400000} function pct(a,b){return b?Math.round(a/b*100):0}
