function professionalizeStructureCards(){
  const answers={
    'squama frontalis':'Чешуя лобной кости','partes orbitales':'Глазничные части лобной кости','facies interna|Теменная кость':'Внутренняя поверхность теменной кости','facies externa|Теменная кость':'Наружная поверхность теменной кости','pars basilaris':'Базилярная часть затылочной кости','partes laterales':'Латеральные части затылочной кости','pars squamosa':'Чешуйчатая часть височной кости','pars petrosa':'Каменистая часть височной кости','corpus|Клиновидная кость':'Тело клиновидной кости','ala minor':'Малое крыло клиновидной кости','lamina cribrosa':'Решётчатая пластинка','crista galli':'Петушиный гребень','corpus maxillae':'Тело верхней челюсти','processus frontalis|Верхняя челюсть':'Лобный отросток верхней челюсти','corpus mandibulae':'Тело нижней челюсти','ramus mandibulae':'Ветвь нижней челюсти','facies lateralis':'Латеральная поверхность скуловой кости','processus frontalis|Скуловая кость':'Лобный отросток скуловой кости','facies externa|Носовая кость':'Наружная поверхность носовой кости','facies interna|Носовая кость':'Внутренняя поверхность носовой кости','crista lacrimalis posterior':'Задний слёзный гребень','sulcus lacrimalis':'Слёзная борозда','lamina horizontalis':'Горизонтальная пластинка нёбной кости','lamina perpendicularis':'Перпендикулярная пластинка нёбной кости','ala vomeris':'Крыло сошника','sulcus vomeris':'Борозда сошника','corpus|Подъязычная кость':'Тело подъязычной кости','cornua majora':'Большие рога подъязычной кости',
    'передняя дуга':'Передняя дуга атланта','задняя дуга':'Задняя дуга атланта','зубовидный отросток':'Зубовидный отросток осевого позвонка','тело|Второй шейный позвонок':'Тело осевого позвонка','тело|Типичный шейный позвонок':'Тело типичного шейного позвонка','позвоночное отверстие':'Позвоночное отверстие типичного шейного позвонка','тело|Грудной позвонок':'Тело грудного позвонка','дуга':'Дуга грудного позвонка','крупное тело':'Крупное тело поясничного позвонка','треугольное позвоночное отверстие':'Треугольное позвоночное отверстие поясничного позвонка','promontorium':'Мыс крестца','facies pelvica':'Тазовая поверхность крестца','cornua coccygea':'Копчиковые рога','vertebrae coccygeae':'Копчиковые позвонки',
    'caput costae':'Головка ребра','collum costae':'Шейка ребра','manubrium sterni':'Рукоятка грудины','corpus sterni':'Тело грудины',
    'extremitas sternalis':'Грудинный конец ключицы','extremitas acromialis':'Акромиальный конец ключицы','spina scapulae':'Ость лопатки','acromion':'Акромион','caput humeri':'Головка плечевой кости','tuberculum majus':'Большой бугорок плечевой кости','caput radii':'Головка лучевой кости','collum radii':'Шейка лучевой кости','olecranon':'Локтевой отросток','processus coronoideus':'Венечный отросток локтевой кости','scaphoideum':'Ладьевидная кость запястья','lunatum':'Полулунная кость','phalanges proximales|Фаланги кисти':'Проксимальные фаланги пальцев кисти','phalanges mediae|Фаланги кисти':'Средние фаланги пальцев кисти',
    'os ilium':'Подвздошная кость','os ischii':'Седалищная кость','caput femoris':'Головка бедренной кости','collum femoris':'Шейка бедренной кости','basis patellae':'Основание надколенника','apex patellae':'Верхушка надколенника','condylus medialis':'Медиальный мыщелок большеберцовой кости','condylus lateralis':'Латеральный мыщелок большеберцовой кости','caput fibulae':'Головка малоберцовой кости','collum fibulae':'Шейка малоберцовой кости','corpus tali':'Тело таранной кости','collum tali':'Шейка таранной кости','tuber calcanei':'Бугор пяточной кости','sustentaculum tali':'Опора таранной кости','basis|Плюсна':'Основание плюсневой кости','corpus|Плюсна':'Тело плюсневой кости','phalanges proximales|Фаланги стопы':'Проксимальные фаланги пальцев стопы','phalanges mediae|Фаланги стопы':'Средние фаланги пальцев стопы',
    'шейный отдел':'Шейный отдел позвоночника','грудной отдел':'Грудной отдел позвоночника'
  };
  GRANULAR_SETS.forEach(s=>s.cards.forEach(c=>{
    if(!/^Как называется структура /.test(c.q)) return;
    const term=(c.q.match(/^Как называется структура (.+?) у /)||[])[1]||'';
    const key=term+'|'+(c.topicKey||'');
    const ans=answers[key]||answers[term]||c.a;
    c.q=`Что означает анатомический термин «${term}»?`;
    c.a=ans;
    c.kind='basic';
    c.explanation=`Термин «${term}» обозначает: ${ans}.`;
  }));
}
professionalizeStructureCards();

function makeProfessionalSets(){
  const sourceByTopic={};
  GRANULAR_SETS.forEach(s=>s.cards.forEach(c=>{if(c.topicKey&&!sourceByTopic[c.topicKey])sourceByTopic[c.topicKey]=c;}));
  const sourceSetForTopic={};
  GRANULAR_SETS.forEach(s=>s.cards.forEach(c=>{if(c.topicKey&&!sourceSetForTopic[c.topicKey])sourceSetForTopic[c.topicKey]=s;}));
  const sets=[];
  PROFESSIONAL_GROUPS.forEach(g=>{
    const cards=[]; g.topics.forEach(t=>{const src=sourceSetForTopic[t]; if(src)cards.push(...src.cards.filter(c=>c.topicKey===t));});
    sets.push({id:g.id,title:g.title,subject:'Анатомия',description:g.desc,tags:['анатомия','системный набор',...g.topics],cards,cover:g.cover,collection:'professional'});
  });
  Object.keys(sourceByTopic).forEach((topic,i)=>{
    const src=sourceSetForTopic[topic];
    const cards=src.cards.filter(c=>c.topicKey===topic);
    const id='topic-'+i+'-'+slug(topic);
    sets.push({id,title:`Анатомия · ${topic}`,subject:'Анатомия',description:`Глубокий набор по теме: ${topic}. Все основные карточки темы собраны отдельно.`,tags:['анатомия','детальный набор',topic],cards,cover:PROFESSIONAL_COVERS[topic],collection:'topic'});
  });
  return sets;
}
function slug(s){return String(s).toLowerCase().replace(/ё/g,'e').replace(/[^a-z0-9а-я]+/gi,'-').replace(/^-|-$/g,'');}
const PROFESSIONAL_SETS=makeProfessionalSets();
function allSets(){return [...PROFESSIONAL_SETS,...GRANULAR_SETS,...DEFAULT_SETS,...state.customSets]}

function coverMarkup(s){
  const src=s.cover || (s.id==='skull-bones'?'data:image/svg+xml;base64,':s.id==='vertebrae'?'data:image/svg+xml;base64,':s.id==='ribs-sternum'?'data:image/svg+xml;base64,':s.id==='upper-limb'?'data:image/svg+xml;base64,':s.id==='lower-limb'?'data:image/svg+xml;base64,':s.id==='axial-skeleton'?'data:image/svg+xml;base64,':'data:image/svg+xml;base64,');
  return `<div class="set-cover set-cover-art"><img src="${esc(src)}" alt="${esc(s.title)}" loading="lazy"><span class="cover-shade"></span></div>`;
}
function setCard(s){const p=setProgress(s);return `<article class="set-card"><div class="set-cover-wrap">${coverMarkup(s)}</div><div class="set-meta"><span class="tag">${esc(s.subject)}</span><span class="tag">${s.cards.length} карточек</span></div><h3>${esc(s.title)}</h3><p>${esc(s.description)}</p><div class="set-footer"><div class="progress"><span style="width:${p}%"></span></div><small>${p}%</small><button class="btn primary" onclick="openStudy('${s.id}','cards')">${p?'Продолжить':'Начать'}</button></div></article>`}

function buildOrder(s,mode){
  const pool=[...s.cards];
  const target=mode==='exam'?Math.min(20,pool.length):mode==='test'?Math.min(12,pool.length):pool.length;
  const remaining=[...pool],out=[];
  let lastTopic='',lastKind='',lastAnswer='';
  while(remaining.length&&out.length<target){
    let candidates=remaining.filter(c=>(!c.topicKey||c.topicKey!==lastTopic));
    if(!candidates.length)candidates=[...remaining];
    let diversified=candidates.filter(c=>(c.kind||'basic')!==lastKind && c.a!==lastAnswer);
    if(diversified.length)candidates=diversified;
    else { diversified=candidates.filter(c=>(c.kind||'basic')!==lastKind); if(diversified.length)candidates=diversified; }
    const pick=candidates[Math.floor(Math.random()*candidates.length)];
    out.push(pick); remaining.splice(remaining.indexOf(pick),1);
    lastTopic=pick.topicKey||''; lastKind=pick.kind||'basic'; lastAnswer=pick.a;
  }
  return out;
}

function resetEditorCounter(){editorN=0;}
function renumberEditorCards(){
  const cards=[...document.querySelectorAll('#editorCards .card-editor')];
  cards.forEach((el,i)=>{const b=el.querySelector('.card-number');if(b)b.textContent=`Карточка ${i+1}`;});
  editorN=cards.length;
}
function removeEditorCard(btn){btn.closest('.card-editor')?.remove();renumberEditorCards();}
function addEditorCard(q='',a=''){
  const el=document.getElementById('editorCards');if(!el)return;
  const n=document.querySelectorAll('#editorCards .card-editor').length+1; editorN=n;
  const d=document.createElement('div');d.className='card-editor';
  d.innerHTML=`<div class="card-editor-head"><b class="card-number">Карточка ${n}</b><button class="btn danger" onclick="removeEditorCard(this)">Удалить</button></div><div class="editor-grid" style="margin-top:10px"><div class="field"><label>Вопрос</label><textarea class="eq" placeholder="Например: Как называется...">${esc(q)}</textarea></div><div class="field"><label>Ответ</label><textarea class="ea" placeholder="Введите точный ответ">${esc(a)}</textarea></div></div>`;
  el.appendChild(d); renumberEditorCards();
}
function createView(){
  resetEditorCounter();
  document.getElementById('view-create').innerHTML=`<h1 class="page-title">Создать набор</h1><p class="page-sub">Создайте собственную базу знаний вручную. Нумерация карточек всегда пересчитывается после удаления.</p><div class="panel"><div class="editor-grid"><div class="field"><label>Название набора</label><input id="newTitle" placeholder="Например: Височная кость"></div><div class="field"><label>Предмет</label><select id="newSubject">${SUBJECTS.map(x=>`<option>${x[0]}</option>`).join('')}<option>Учебник</option></select></div><div class="field" style="grid-column:1/-1"><label>Описание</label><textarea id="newDesc" placeholder="Кратко опишите содержание набора"></textarea></div></div><div class="section-head" style="margin-top:22px"><div><h3>Карточки</h3><p>Добавляйте только полноценные пары «вопрос → ответ». Порядковый номер не хранится в памяти и пересчитывается заново.</p></div><button class="btn soft" onclick="addEditorCard()">${icon('plus')} Добавить карточку</button></div><div id="editorCards"></div><div style="margin-top:16px;display:flex;gap:8px;flex-wrap:wrap"><button class="btn primary" onclick="saveNewSet()">Создать набор</button><button class="btn" onclick="showView('sets')">Отмена</button></div></div>`;
  addEditorCard(); hydrateIcons();
}
function saveNewSet(){
  const title=document.getElementById('newTitle')?.value.trim(),subject=document.getElementById('newSubject')?.value,desc=document.getElementById('newDesc')?.value.trim();
  const cards=[...document.querySelectorAll('#editorCards .card-editor')].map((x,i)=>({id:'custom-'+Date.now()+'-'+i,q:x.querySelector('.eq').value.trim(),a:x.querySelector('.ea').value.trim(),kind:'basic',tags:['пользовательская'],source:null})).filter(x=>x.q&&x.a);
  if(!title||!cards.length){toast('Укажите название и заполните хотя бы одну карточку');return}
  state.customSets.unshift({id:'set-'+Date.now(),title,subject,description:desc||'Пользовательский набор',tags:['пользовательский'],cards});save();toast('Набор создан');showView('sets');
}

function finishSession(){
  if(current.session&&current.session.answers){state.sessions.unshift({...current.session});state.sessions=state.sessions.slice(0,100);save();if(current.session.mode==='test'||current.session.mode==='exam')toast(`Результат: ${current.session.correct}/${current.session.answers}`);}
  current.session=null;
}
function exitStudy(){
  finishSession();
  history.replaceState(null,'',location.href.split('#')[0]);
  current={setId:current.setId,index:0,mode:'cards',revealed:false,session:null,options:null,order:[]};
  showView('sets');
}
function backToPreviousQuestion(){
  if(!current?.order?.length||current.index<=0){toast('Это первая карточка в сессии');return;}
  current.index--;current.revealed=false;current.options=null;studyView();
}
function randomJump(){
  if(!current?.order?.length||current.order.length<2)return;
  let n=current.index;while(n===current.index)n=Math.floor(Math.random()*current.order.length);
  current.index=n;current.revealed=false;current.options=null;studyView();
}
function studyView(){
  const s=getSet(current.setId)||allSets()[0],c=currentCard(); if(!c)return;
  const total=current.order?.length||s.cards.length,kind=c.kind||'basic'; let body='';
  const src=c.source?`<div class="card-source">${icon('book')}<span>${esc(c.source.name)} · ${esc(c.source.chapterTitle||'раздел')}</span></div>`:'';
  const img=visualMarkup(c);
  const explanation=c.explanation?`<div class="answer-note"><b>Почему это важно</b><span>${esc(c.explanation)}</span></div>`:'';
  if(current.mode==='cards'||current.mode==='learn'){
    body=`<div class="flashcard ${kind==='image_mcq'?'visual-card':''}"><div class="type">${kind==='image_mcq'?'ВИЗУАЛЬНАЯ КАРТОЧКА':current.mode==='learn'?'ИЗУЧЕНИЕ':'КАРТОЧКИ'} · ${current.index+1}/${total}</div>${img}<h2>${esc(c.q)}</h2>${src}<div class="answer ${current.revealed?'':'hidden'}"><span class="eyebrow">ОТВЕТ</span><p>${esc(c.a)}</p>${explanation}</div>${current.revealed?'':'<button class="btn primary" onclick="reveal()">Показать ответ</button>'}</div>${current.revealed?`<div class="study-actions"><button class="grade again" onclick="grade('again')">Снова<small>короткий интервал</small></button><button class="grade hard" onclick="grade('hard')">Сложно<small>повторить раньше</small></button><button class="grade good" onclick="grade('good')">Хорошо<small>обычный интервал</small></button><button class="grade easy" onclick="grade('easy')">Легко<small>длинный интервал</small></button></div>`:''}`;
  } else if(current.mode==='write'){
    body=`<div class="flashcard">${img}<div class="type">НАПИСАНИЕ · ${current.index+1}/${total}</div><h2>${esc(c.q)}</h2>${src}<div class="write-box"><input id="writeAnswer" placeholder="Введите ответ…" autocomplete="off"><button class="btn primary" onclick="checkWrite()">Проверить</button></div><div id="writeResult"></div></div>`;
  } else if(current.mode==='test'||current.mode==='exam'){
    current.options=current.options||c.options||makeOptions(s,c); const opts=current.options;
    body=`<div class="flashcard ${kind==='image_mcq'?'visual-card':''}">${img}<div class="type">${current.mode==='exam'?'ЭКЗАМЕН':'ТЕСТ'} · ${current.index+1}/${total}</div><h2>${esc(c.q)}</h2>${src}<div class="quiz-options">${opts.map((o,i)=>`<button class="option" onclick="chooseOption(${i})">${String.fromCharCode(65+i)} · ${esc(o)}</button>`).join('')}</div></div>`;
  }
  document.getElementById('view-study').innerHTML=`<div class="study-shell"><div class="study-head"><div><div class="study-nav"><button class="btn soft" onclick="exitStudy()">← Наборы</button>${current.index>0?`<button class="btn soft" onclick="backToPreviousQuestion()">← Предыдущая</button>`:''}</div><h2>${esc(s.title)}</h2><small class="muted">${esc(s.subject)} · ${modeLabel(current.mode)}</small></div><button class="mode-picker-btn" onclick="openModeSheet()"><span class="mode-picker-icon">${icon(modeIcon(current.mode))}</span><span><b>${modeLabel(current.mode)}</b><small>сменить режим</small></span><span class="chev">⌄</span></button></div><div class="study-progress"><span style="width:${pct(current.index,total)}%"></span></div>${body}<div class="study-footer"><span>Вопрос ${current.index+1} из ${total}</span><button class="btn soft" onclick="randomJump()">Случайный вопрос</button></div><div class="form-note">Алгоритм сессии учитывает тему, тип карточки и предыдущий ответ; зеркальные вопросы стараются не идти подряд.</div></div>`;
  hydrateIcons();
}

function boot(){applyTheme();hydrateIcons();home();if(state.betaAccepted)document.getElementById('betaNotice').style.display='none';if('serviceWorker' in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});const prev=localStorage.getItem(BUILD_KEY);if(prev&&prev!==APP_VERSION){clearCaches().catch(()=>{});localStorage.setItem(BUILD_KEY,APP_VERSION)}else localStorage.setItem(BUILD_KEY,APP_VERSION)}boot();
